<?php $title='Achievements';$unlocked=count(array_filter($achievements,fn($item)=>$item['unlocked_at'])); ?>
<div class="mb-6"><p class="text-sm font-semibold text-violet-400">🏆 <?= $unlocked ?> / <?= count($achievements) ?> UNLOCKED</p><h1 class="text-3xl font-black">Achievements</h1><p class="mt-1 text-zinc-400">A record of consistency, progression, and milestones.</p></div>
<?php $category=null;foreach($achievements as $achievement):if($category!==$achievement['category']):if($category!==null):?></div><?php endif;$category=$achievement['category'];?><h2 class="mb-3 mt-7 text-lg font-bold"><?= e($category) ?></h2><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><?php endif;$isUnlocked=(bool)$achievement['unlocked_at'];?><article class="rounded-2xl border p-4 <?= $isUnlocked?'border-violet-700/60 bg-gradient-to-br from-violet-950/35 to-zinc-900':'border-zinc-800 bg-zinc-900/50 opacity-60 grayscale' ?>"><div class="flex items-start justify-between"><span class="text-3xl"><?= $isUnlocked?e($achievement['icon']):'🔒' ?></span><?php if($isUnlocked):?><span class="text-xs text-emerald-400">Unlocked <?= e(date('M j, Y',strtotime($achievement['unlocked_at']))) ?></span><?php endif;?></div><h3 class="mt-3 font-bold"><?= e($achievement['name']) ?></h3><p class="mt-1 text-sm text-zinc-400"><?= e($achievement['is_hidden']&&!$isUnlocked?$achievement['description']:$achievement['description']) ?></p><?php if(!$isUnlocked&&$achievement['requirement_value']):?><div class="mt-3"><div class="mb-1 flex justify-between text-xs text-zinc-500"><span><?= e(number_format((float)$achievement['current_value'],0)) ?> / <?= e(number_format((float)$achievement['requirement_value'],0)) ?></span><span><?= (int)$achievement['progress_percent'] ?>%</span></div><div class="h-1.5 overflow-hidden rounded-full bg-zinc-800"><div class="h-full bg-violet-600" style="width:<?= (int)$achievement['progress_percent'] ?>%"></div></div></div><?php endif;?></article><?php endforeach;?></div>
